import json
path='/Users/sashaabramovich/.claude/projects/-private-tmp-live-spec-roadmap-wave/270e2224-42cb-4817-ace0-cd02b86f69b7.jsonl'
# map tool_use_id -> command for bash, then find results
lines=[json.loads(l) for l in open(path)]
tool_calls={}
for d in lines:
    ts=d.get('timestamp','') or ''
    if ts<'2026-08-18T18:17:00Z': continue
    if d.get('type')=='assistant':
        content=d.get('message',{}).get('content')
        if isinstance(content,list):
            for block in content:
                if isinstance(block,dict) and block.get('type')=='tool_use' and block.get('name')=='Bash':
                    cmd=block.get('input',{}).get('command','')
                    if 'git push' in cmd or 'gh run' in cmd or 'gh pr' in cmd:
                        tool_calls[block.get('id')]=(ts,cmd)

# find tool_result for these
results={}
for d in lines:
    if d.get('type')=='user':
        content=d.get('message',{}).get('content')
        if isinstance(content,list):
            for block in content:
                if isinstance(block,dict) and block.get('type')=='tool_result':
                    tid=block.get('tool_use_id')
                    if tid in tool_calls:
                        c=block.get('content')
                        if isinstance(c,list):
                            txt=' '.join(b.get('text','') for b in c if isinstance(b,dict))
                        else:
                            txt=str(c)
                        results[tid]=txt

for tid,(ts,cmd) in tool_calls.items():
    print('===',ts,'===')
    print('CMD:', cmd[:500])
    print('RESULT:', results.get(tid,'<no result found>')[:800])
    print()
